{
  "controlWidth" : 12,
  "label" : "TextBlock1",
  "text" : "<div style=\"font-size: 15px; border-radius: 10px; padding: 10px; height: 200px; overflow-x: hidden; overflow-y: auto; background-color: #e8e8e8;\">\n<p><strong>Apologise to the customer:</strong></p>\n<p>&nbsp;</p>\n<p>&ldquo;I&rsquo;m sorry you had to make a complaint to have this issue resolved.&rdquo;</p>\n<p>OR</p>\n<p>&ldquo;I&rsquo;m sorry to hear this isn&rsquo;t right.&rdquo;</p>\n<p><strong>&nbsp;</strong></p>\n<p><strong>Acknowledge concern:<br /><br /></strong></p>\n<p>&ldquo;Thank you for raising this with us. I&rsquo;ve recorded your concerns and this will be considered as part of our internal review.&rdquo;</p>\n</div>",
  "show" : {
    "group" : {
      "operator" : "AND",
      "rules" : [ {
        "data" : "Address / personal details incorrect",
        "condition" : "=",
        "field" : "ApologiseStatement:TalkTrackApologise:selectedButtonName"
      } ]
    }
  },
  "dataJSON" : false,
  "HTMLTemplateId" : "",
  "textKey" : "",
  "sanitize" : false
}

